'use client'

import * as React from 'react'

import {
  dismissalExpiry,
  dismissalKey,
  matchRoute,
  selectPromotions,
  type Promotion,
  type PromotionPlacement,
  type PromotionSelection,
} from './promotion'

/* -------------------------------------------------------------------------- */
/*  Contracts the host provides                                               */
/* -------------------------------------------------------------------------- */

/** Records the provider chooses from. An array, or anything that can load one. */
export type PromotionSource =
  | readonly Promotion[]
  | { load: (signal: AbortSignal) => Promise<readonly Promotion[]> }

export type PromotionEvent = {
  type: 'impression' | 'click' | 'dismiss'
  id: string
  placement: PromotionPlacement
  campaign?: string
}

/** Where dismissals live. Values are the epoch ms the visitor dismissed at. */
export type DismissalStore = {
  get: (key: string) => number | null
  set: (
    key: string,
    dismissedAt: number,
    scope: 'session' | 'persistent',
  ) => void
}

export type PromotionLinkProps = {
  href: string
  className?: string
  children: React.ReactNode
  onClick?: () => void
  target?: string
  rel?: string
}

/* -------------------------------------------------------------------------- */
/*  Defaults                                                                  */
/* -------------------------------------------------------------------------- */

function safeStorage(kind: 'local' | 'session'): Storage | null {
  try {
    return kind === 'local' ? window.localStorage : window.sessionStorage
  } catch {
    return null
  }
}

/** localStorage for lasting dismissals, sessionStorage for per-visit ones. */
export const browserDismissalStore: DismissalStore = {
  get(key) {
    for (const kind of ['session', 'local'] as const) {
      try {
        const raw = safeStorage(kind)?.getItem(key)
        const value = raw ? Number(raw) : Number.NaN
        if (Number.isFinite(value)) return value
      } catch {
        // Storage can throw in private windows; treat as not dismissed.
      }
    }
    return null
  },
  set(key, dismissedAt, scope) {
    try {
      safeStorage(scope === 'session' ? 'session' : 'local')?.setItem(
        key,
        String(dismissedAt),
      )
    } catch {
      // Dismissal still applies for this render via provider state.
    }
  },
}

function DefaultLink({
  href,
  className,
  children,
  onClick,
  target,
  rel,
}: PromotionLinkProps) {
  return (
    <a
      href={href}
      className={className}
      onClick={onClick}
      target={target}
      rel={rel}
    >
      {children}
    </a>
  )
}

/* -------------------------------------------------------------------------- */
/*  Context                                                                   */
/* -------------------------------------------------------------------------- */

type PromotionContextValue = {
  /** Null until mounted: time-dependent UI never renders on the server. */
  now: number | null
  selection: PromotionSelection
  bar: Promotion | null
  dialog: Promotion | null
  card: (slot: string) => Promotion | null
  dismiss: (promotion: Promotion) => void
  report: (event: PromotionEvent) => void
  Link: React.ComponentType<PromotionLinkProps>
  timeZone?: string
}

const PromotionContext = React.createContext<PromotionContextValue | null>(null)

export function usePromotions(): PromotionContextValue {
  const value = React.useContext(PromotionContext)
  if (!value)
    throw new Error(
      'Promotion components must be rendered inside <PromotionProvider>.',
    )
  return value
}

/* -------------------------------------------------------------------------- */
/*  Provider                                                                  */
/* -------------------------------------------------------------------------- */

export type PromotionProviderProps = {
  source: PromotionSource
  /** The current route. Pass your router's pathname, e.g. `usePathname()`. */
  pathname: string
  /** Injectable clock for previews and tests. */
  now?: () => number
  /** How often the clock is re-read, so windows open and close on time. */
  tickMs?: number
  storage?: DismissalStore
  /** Route patterns where the bar and dialog never appear (checkout, sign-in). */
  suppressOn?: readonly string[]
  /** A dialog waits for this much time and scroll depth before it may open. */
  dialogEngagement?: { delayMs?: number; scrollDepth?: number }
  onEvent?: (event: PromotionEvent) => void
  /** Your framework's link, so internal CTAs navigate client-side. */
  linkComponent?: React.ComponentType<PromotionLinkProps>
  /** Shown next to schedule text in countdowns and editors. */
  timeZone?: string
  children: React.ReactNode
}

function useLoadedRecords(source: PromotionSource): readonly Promotion[] {
  const isArray = Array.isArray(source)
  const [loaded, setLoaded] = React.useState<readonly Promotion[]>([])

  React.useEffect(() => {
    if (Array.isArray(source)) return
    const controller = new AbortController()
    ;(source as Exclude<PromotionSource, readonly Promotion[]>)
      .load(controller.signal)
      .then((records) => {
        if (!controller.signal.aborted) setLoaded(records)
      })
      .catch(() => {
        // A promotion is never worth an error screen. Show nothing.
      })
    return () => controller.abort()
  }, [source])

  return isArray ? (source as readonly Promotion[]) : loaded
}

function createClockStore(now: () => number, tickMs: number) {
  let value = now()
  return {
    subscribe(onChange: () => void) {
      value = now()
      const timer = window.setInterval(() => {
        value = now()
        onChange()
      }, tickMs)
      return () => window.clearInterval(timer)
    },
    get: () => value,
  }
}

const serverClock = () => null

/**
 * The clock as an external store: SSR and hydration read null, so nothing
 * time-dependent renders until the browser's own clock is known.
 */
function useClock(now: () => number, tickMs: number): number | null {
  const store = React.useMemo(
    () => createClockStore(now, tickMs),
    [now, tickMs],
  )
  return React.useSyncExternalStore(store.subscribe, store.get, serverClock)
}

/** Engagement is per page: navigating resets it without a state write. */
function useEngaged(
  pathname: string,
  {
    delayMs = 8000,
    scrollDepth = 0.3,
  }: { delayMs?: number; scrollDepth?: number },
): boolean {
  const [engagedOn, setEngagedOn] = React.useState<string | null>(null)

  React.useEffect(() => {
    let waited = delayMs <= 0
    let scrolled = scrollDepth <= 0
    const check = () => {
      if (waited && scrolled) setEngagedOn(pathname)
    }
    const onScroll = () => {
      const max = document.documentElement.scrollHeight - window.innerHeight
      // A page too short to scroll counts as read.
      const depth = max <= 0 ? 1 : window.scrollY / max
      if (depth >= scrollDepth) {
        scrolled = true
        check()
      }
    }
    const timer = window.setTimeout(() => {
      waited = true
      onScroll()
      check()
    }, delayMs)
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      window.clearTimeout(timer)
      window.removeEventListener('scroll', onScroll)
    }
  }, [pathname, delayMs, scrollDepth])

  return engagedOn === pathname
}

const NO_ROUTES: readonly string[] = []
const DEFAULT_ENGAGEMENT: { delayMs?: number; scrollDepth?: number } = {}

export function PromotionProvider({
  source,
  pathname,
  now: readNow = Date.now,
  tickMs = 60_000,
  storage = browserDismissalStore,
  suppressOn = NO_ROUTES,
  dialogEngagement = DEFAULT_ENGAGEMENT,
  onEvent,
  linkComponent = DefaultLink,
  timeZone,
  children,
}: PromotionProviderProps) {
  const records = useLoadedRecords(source)
  const now = useClock(readNow, tickMs)
  const engaged = useEngaged(pathname, dialogEngagement)
  // Dismissals made this render cycle apply immediately, even if storage throws.
  const [dismissedNow, setDismissedNow] = React.useState<ReadonlySet<string>>(
    new Set(),
  )

  const report = React.useCallback(
    (event: PromotionEvent) => onEvent?.(event),
    [onEvent],
  )

  const isDismissed = React.useCallback(
    (promotion: Promotion) => {
      const key = dismissalKey(promotion)
      if (dismissedNow.has(key)) return true
      if (now === null) return true
      const at = storage.get(key)
      if (at === null) return false
      const expiry = dismissalExpiry(promotion.dismiss, at)
      return expiry === null || now < expiry
    },
    [dismissedNow, now, storage],
  )

  const dismiss = React.useCallback(
    (promotion: Promotion) => {
      const key = dismissalKey(promotion)
      storage.set(
        key,
        Date.now(),
        promotion.dismiss.mode === 'session' ? 'session' : 'persistent',
      )
      setDismissedNow((previous) => new Set(previous).add(key))
      report({
        type: 'dismiss',
        id: promotion.id,
        placement: promotion.placement,
        campaign: promotion.campaign,
      })
    },
    [report, storage],
  )

  const value = React.useMemo<PromotionContextValue>(() => {
    const selection =
      now === null
        ? { cards: {} }
        : selectPromotions(records, { pathname, now })
    const suppressed = suppressOn.some((pattern) =>
      matchRoute(pattern, pathname),
    )

    const barCandidate =
      !suppressed && selection.bar && !isDismissed(selection.bar)
        ? selection.bar
        : null
    const dialogCandidate =
      !suppressed && selection.dialog && !isDismissed(selection.dialog)
        ? selection.dialog
        : null

    // One intrusive surface at a time. A dialog only outranks a visible bar
    // when its priority is strictly higher, and then the bar steps aside.
    const dialog =
      dialogCandidate &&
      engaged &&
      (!barCandidate || dialogCandidate.priority > barCandidate.priority)
        ? dialogCandidate
        : null
    const bar = dialog ? null : barCandidate

    return {
      now,
      selection,
      bar,
      dialog,
      card: (slot) => {
        const candidate = selection.cards[slot]
        return candidate && !isDismissed(candidate) ? candidate : null
      },
      dismiss,
      report,
      Link: linkComponent,
      timeZone,
    }
  }, [
    dismiss,
    engaged,
    isDismissed,
    linkComponent,
    now,
    pathname,
    records,
    report,
    suppressOn,
    timeZone,
  ])

  return (
    <PromotionContext.Provider value={value}>
      {children}
    </PromotionContext.Provider>
  )
}

/* -------------------------------------------------------------------------- */
/*  Impressions                                                               */
/* -------------------------------------------------------------------------- */

/**
 * Fires once when at least half the element has been visible for a second.
 * Rendering is not an impression; being seen is.
 */
export function useImpression(
  promotion: Promotion | null,
  onImpression: ((promotion: Promotion) => void) | undefined,
) {
  const ref = React.useRef<HTMLElement | null>(null)
  const seen = React.useRef<string | null>(null)

  React.useEffect(() => {
    const element = ref.current
    if (!promotion || !element || !onImpression) return
    if (seen.current === promotion.id) return
    if (typeof IntersectionObserver === 'undefined') return

    let timer: number | undefined
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          timer = window.setTimeout(() => {
            seen.current = promotion.id
            onImpression(promotion)
            observer.disconnect()
          }, 1000)
        } else if (timer !== undefined) {
          window.clearTimeout(timer)
          timer = undefined
        }
      },
      { threshold: 0.5 },
    )
    observer.observe(element)
    return () => {
      if (timer !== undefined) window.clearTimeout(timer)
      observer.disconnect()
    }
  }, [promotion, onImpression])

  return ref
}

'use client'

import * as React from 'react'
import { IconArrowRight, IconArrowUpRight, IconX } from '@tabler/icons-react'
import { cn } from '@/lib/utils'

import { Button } from '@/components/ui/button'
import {
  countdownVisible,
  formatTimeLeft,
  type Promotion,
  type PromotionContent,
  type PromotionTone,
} from './promotion'
import type { PromotionLinkProps } from './promotion-provider'

/**
 * Presentational pieces shared by the live renderers and the editor preview.
 * They take a promotion and callbacks, never the provider, so a draft can be
 * previewed exactly as it will render.
 *
 * Tones read shadcn tokens. `highlight` reads `--promo-highlight` and
 * `--promo-highlight-foreground` when a theme defines them, and falls back to
 * the accent pair, so a brand colour can be dropped in without forking.
 */
export const promotionToneClasses: Record<PromotionTone, string> = {
  neutral: 'bg-muted text-foreground',
  brand: 'bg-primary text-primary-foreground',
  highlight:
    'bg-[var(--promo-highlight,var(--accent))] text-[var(--promo-highlight-foreground,var(--accent-foreground))]',
}

export type PreviewablePromotion = PromotionContent &
  Partial<Pick<Promotion, 'id' | 'campaign'>>

type ViewProps = {
  promotion: PreviewablePromotion
  now: number | null
  Link?: React.ComponentType<PromotionLinkProps>
  onClick?: () => void
  onDismiss?: () => void
}

function PlainLink({
  href,
  className,
  children,
  onClick,
  target,
  rel,
}: PromotionLinkProps) {
  return (
    <a
      href={href}
      className={className}
      onClick={onClick}
      target={target}
      rel={rel}
    >
      {children}
    </a>
  )
}

function Countdown({
  promotion,
  now,
}: {
  promotion: PreviewablePromotion
  now: number | null
}) {
  if (now === null || !countdownVisible(promotion, now)) return null
  const label = formatTimeLeft(promotion.endsAt, now)
  if (!label) return null
  return (
    <span className="bg-background/15 rounded-md px-1.5 py-0.5 text-xs font-medium whitespace-nowrap tabular-nums ring-1 ring-current/15">
      {label}
    </span>
  )
}

function CtaLink({
  promotion,
  Link = PlainLink,
  onClick,
  className,
}: Pick<ViewProps, 'promotion' | 'Link' | 'onClick'> & { className?: string }) {
  const cta = promotion.cta
  if (!cta) return null
  const Icon = cta.external ? IconArrowUpRight : IconArrowRight
  return (
    <Link
      href={cta.href}
      onClick={onClick}
      className={cn(
        'group/cta inline-flex items-center gap-1 font-medium',
        className,
      )}
      {...(cta.external
        ? { target: '_blank', rel: 'noopener noreferrer' }
        : {})}
    >
      {cta.label}
      <Icon
        aria-hidden
        className="size-4 transition-transform duration-200 group-hover/cta:translate-x-0.5 motion-reduce:transition-none"
      />
      {cta.external ? (
        <span className="sr-only"> (opens in a new tab)</span>
      ) : null}
    </Link>
  )
}

function DismissButton({
  onDismiss,
  label,
}: {
  onDismiss?: () => void
  label: string
}) {
  if (!onDismiss) return null
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-sm"
      onClick={onDismiss}
      aria-label={label}
      className="shrink-0 text-current hover:bg-current/10 hover:text-current"
    >
      <IconX aria-hidden />
    </Button>
  )
}

/* -------------------------------------------------------------------------- */

export function PromoBarView({
  promotion,
  now,
  Link,
  onClick,
  onDismiss,
}: ViewProps) {
  return (
    <div
      role="region"
      aria-label={promotion.eyebrow ?? 'Announcement'}
      className={cn('w-full text-sm', promotionToneClasses[promotion.tone])}
    >
      <div className="mx-auto flex max-w-screen-xl items-center gap-3 px-4 py-2 sm:px-6">
        <p className="flex min-w-0 flex-1 flex-wrap items-center justify-center gap-x-2 gap-y-1 text-center">
          {promotion.eyebrow ? (
            <span className="font-medium opacity-80">{promotion.eyebrow}</span>
          ) : null}
          <span className="font-medium">{promotion.title}</span>
          {promotion.body ? (
            <span className="hidden opacity-80 md:inline">
              {promotion.body}
            </span>
          ) : null}
          <Countdown promotion={promotion} now={now} />
          <CtaLink
            promotion={promotion}
            Link={Link}
            onClick={onClick}
            className="underline decoration-current/40 underline-offset-4 hover:decoration-current"
          />
        </p>
        <DismissButton onDismiss={onDismiss} label="Dismiss announcement" />
      </div>
    </div>
  )
}

export function PromoCardView({
  promotion,
  now,
  Link,
  onClick,
  onDismiss,
  className,
}: ViewProps & { className?: string }) {
  const media = promotion.media
  return (
    <aside
      aria-label={promotion.eyebrow ?? promotion.title}
      className={cn(
        'relative flex overflow-hidden rounded-xl border border-border/60 text-sm',
        media ? 'flex-col sm:flex-row' : 'flex-col',
        promotionToneClasses[promotion.tone],
        className,
      )}
    >
      {media ? (
        // Plain img: the registry must not assume a framework image loader.
        // oxlint-disable-next-line nextjs/no-img-element
        <img
          src={media.src}
          alt={media.alt}
          width={media.width}
          height={media.height}
          loading="lazy"
          decoding="async"
          className="aspect-[16/9] w-full object-cover sm:aspect-auto sm:w-2/5"
        />
      ) : null}
      <div className="flex flex-1 flex-col gap-2 p-4 sm:p-5">
        <div className="flex items-center gap-2">
          {promotion.eyebrow ? (
            <span className="text-xs font-medium tracking-wide uppercase opacity-75">
              {promotion.eyebrow}
            </span>
          ) : null}
          <Countdown promotion={promotion} now={now} />
        </div>
        <p className="text-base leading-snug font-medium text-balance">
          {promotion.title}
        </p>
        {promotion.body ? (
          <p className="leading-relaxed opacity-80">{promotion.body}</p>
        ) : null}
        <CtaLink
          promotion={promotion}
          Link={Link}
          onClick={onClick}
          className="mt-1 self-start underline decoration-current/30 underline-offset-4 hover:decoration-current"
        />
      </div>
      {onDismiss ? (
        <div className="absolute top-2 right-2">
          <DismissButton
            onDismiss={onDismiss}
            label={`Dismiss ${promotion.title}`}
          />
        </div>
      ) : null}
    </aside>
  )
}

type TextComponent = React.ComponentType<{
  className?: string
  children?: React.ReactNode
}>

function DefaultTitle({ children }: { children?: React.ReactNode }) {
  return <p className="text-lg font-medium">{children}</p>
}

function DefaultDescription({ children }: { children?: React.ReactNode }) {
  return <p className="text-muted-foreground text-sm">{children}</p>
}

/**
 * The inside of the dialog or sheet; the surface itself is chosen by
 * PromoDialog, which passes its own Title and Description so the popup is
 * labelled for assistive technology.
 */
export function PromoDialogContentView({
  promotion,
  now,
  Link,
  onClick,
  onDismiss,
  Title = DefaultTitle,
  Description = DefaultDescription,
}: ViewProps & { Title?: TextComponent; Description?: TextComponent }) {
  const media = promotion.media
  return (
    <div className="flex flex-col gap-4">
      {media ? (
        // oxlint-disable-next-line nextjs/no-img-element
        <img
          src={media.src}
          alt={media.alt}
          width={media.width}
          height={media.height}
          decoding="async"
          className="aspect-[16/9] w-full rounded-lg object-cover"
        />
      ) : null}
      <div className="flex flex-col gap-1.5">
        <div className="flex items-center gap-2">
          {promotion.eyebrow ? (
            <span className="text-muted-foreground text-xs font-medium tracking-wide uppercase">
              {promotion.eyebrow}
            </span>
          ) : null}
          <span className="text-foreground">
            <Countdown promotion={promotion} now={now} />
          </span>
        </div>
        <Title className="text-lg">{promotion.title}</Title>
        {promotion.body ? <Description>{promotion.body}</Description> : null}
      </div>
      <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
        {onDismiss ? (
          <Button type="button" variant="ghost" onClick={onDismiss}>
            Not now
          </Button>
        ) : null}
        {promotion.cta ? (
          <Button
            nativeButton={false}
            render={
              <CtaLink
                promotion={promotion}
                Link={Link}
                onClick={onClick}
                className="gap-1"
              />
            }
          />
        ) : null}
      </div>
    </div>
  )
}
